'use client';

import { useState } from 'react';
import { updateCategoryStatus } from '@/lib/api-client/category-client';

interface CategoryStatusToggleProps {
  id: string;
  initialStatus: 'Active' | 'Inactive';
  onStatusChange: (id: string, newStatus: 'Active' | 'Inactive') => void;
}

export default function CategoryStatusToggle({ 
  id, 
  initialStatus,
  onStatusChange
}: CategoryStatusToggleProps) {
  const [status, setStatus] = useState<'Active' | 'Inactive'>(initialStatus);
  const [isUpdating, setIsUpdating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  const toggleStatus = async () => {
    setIsUpdating(true);
    setError(null);
    
    try {
      const newStatus = status === 'Active' ? 'Inactive' : 'Active';
      const success = await updateCategoryStatus(id, newStatus);
      
      if (success) {
        setStatus(newStatus);
        onStatusChange(id, newStatus);
      } else {
        setError('Failed to update status');
      }
    } catch (error) {
      console.error('Error updating category status:', error);
      setError('An error occurred while updating status');
    } finally {
      setIsUpdating(false);
    }
  };
  
  return (
    <div className="flex items-center">
      <button
        onClick={toggleStatus}
        disabled={isUpdating}
        className={`
          relative inline-flex h-6 w-11 items-center rounded-full 
          ${status === 'Active' ? 'bg-blue-600' : 'bg-gray-200'} 
          transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2
          ${isUpdating ? 'opacity-50 cursor-not-allowed' : ''}
        `}
        aria-pressed={status === 'Active'}
        aria-label={`Toggle status to ${status === 'Active' ? 'Inactive' : 'Active'}`}
      >
        <span
          className={`
            ${status === 'Active' ? 'translate-x-6' : 'translate-x-1'} 
            inline-block h-4 w-4 transform rounded-full bg-white transition-transform
          `}
        />
      </button>
      <span className="ml-2 text-sm text-gray-600">
        {isUpdating ? 'Updating...' : status}
      </span>
      {error && <p className="ml-2 text-xs text-red-500">{error}</p>}
    </div>
  );
} 