'use client';

import { useState, useEffect } from 'react';
import { createCategory, updateCategory } from '@/lib/api-client/category-client';

interface CategoryFormProps {
  categoryId?: string;
  initialData?: {
    name: string;
    slug: string;
    description: string;
    status: 'Active' | 'Inactive';
  };
  onSuccess: (id?: string) => void;
  onCancel: () => void;
}

export default function CategoryForm({
  categoryId,
  initialData,
  onSuccess,
  onCancel
}: CategoryFormProps) {
  const isEditing = !!categoryId;
  console.log(`CategoryForm initialized - Mode: ${isEditing ? 'Edit' : 'Create'}`);
  if (isEditing) {
    console.log(`Editing category with ID: ${categoryId}`);
    console.log('Initial data:', initialData);
  }
  
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    description: '',
    status: 'Active' as 'Active' | 'Inactive'
  });
  
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  
  useEffect(() => {
    if (initialData) {
      console.log('Setting form data from initialData');
      setFormData({
        name: initialData.name,
        slug: initialData.slug,
        description: initialData.description,
        status: initialData.status
      });
    }
  }, [initialData]);
  
  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // Clear error for this field
    if (errors[name]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[name];
        return newErrors;
      });
    }
  };
  
  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};
    
    if (!formData.name.trim()) {
      newErrors.name = 'Name is required';
    }
    
    if (!formData.slug.trim()) {
      newErrors.slug = 'Slug is required';
    } else if (!/^[a-z0-9-]+$/.test(formData.slug)) {
      newErrors.slug = 'Slug can only contain lowercase letters, numbers, and hyphens';
    }
    
    if (!formData.description.trim()) {
      newErrors.description = 'Description is required';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };
  
  const handleGenerateSlug = () => {
    if (formData.name) {
      const slug = formData.name
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')  // Remove special characters
        .replace(/\s+/g, '-')          // Replace spaces with hyphens
        .replace(/-+/g, '-');          // Replace multiple hyphens with a single hyphen
      
      setFormData(prev => ({
        ...prev,
        slug
      }));
    }
  };
  
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      console.log('Form validation failed');
      return;
    }
    
    setIsSubmitting(true);
    console.log(`Submitting form in ${isEditing ? 'edit' : 'create'} mode`);
    console.log('Form data to submit:', formData);
    
    try {
      if (isEditing && categoryId) {
        // Update existing category
        console.log(`Updating category ${categoryId}...`);
        const success = await updateCategory(categoryId, formData);
        
        if (success) {
          console.log('Category updated successfully');
          onSuccess(categoryId);
        } else {
          console.error('Category update failed - server returned false');
          setErrors({ form: 'Failed to update category. Please try again.' });
        }
      } else {
        // Create new category
        console.log('Creating new category...');
        const newCategoryId = await createCategory(formData);
        
        if (newCategoryId) {
          console.log(`Category created successfully with ID: ${newCategoryId}`);
          onSuccess(newCategoryId);
        } else {
          console.error('Category creation failed - no ID returned');
          setErrors({ form: 'Failed to create category. Please try again.' });
        }
      }
    } catch (error) {
      console.error('Error submitting category form:', error);
      setErrors({ form: 'An error occurred while processing your request. Please try again.' });
    } finally {
      setIsSubmitting(false);
    }
  };
  
  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {errors.form && (
        <div className="bg-red-50 p-4 rounded-md">
          <p className="text-sm text-red-700">{errors.form}</p>
        </div>
      )}
      
      <div>
        <label htmlFor="name" className="block text-sm font-medium text-gray-700 mb-1">
          Category Name <span className="text-red-500">*</span>
        </label>
        <div className="mt-1">
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            className={`block w-full rounded-md border ${
              errors.name ? 'border-red-300' : 'border-gray-300'
            } shadow-sm py-2 px-3 focus:border-blue-500 focus:ring-blue-500`}
          />
          {errors.name && (
            <p className="mt-1 text-sm text-red-600">{errors.name}</p>
          )}
        </div>
      </div>
      
      <div>
        <label htmlFor="slug" className="block text-sm font-medium text-gray-700 mb-1">
          Slug <span className="text-red-500">*</span>
        </label>
        <div className="mt-1 flex rounded-md shadow-sm">
          <input
            type="text"
            id="slug"
            name="slug"
            value={formData.slug}
            onChange={handleChange}
            className={`block w-full rounded-l-md border ${
              errors.slug ? 'border-red-300' : 'border-gray-300'
            } shadow-sm py-2 px-3 focus:border-blue-500 focus:ring-blue-500`}
          />
          <button
            type="button"
            onClick={handleGenerateSlug}
            className="inline-flex items-center px-3 rounded-r-md border border-l-0 border-gray-300 bg-gray-50 text-gray-500 text-sm"
          >
            Generate
          </button>
        </div>
        {errors.slug && (
          <p className="mt-1 text-sm text-red-600">{errors.slug}</p>
        )}
      </div>
      
      <div>
        <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-1">
          Description <span className="text-red-500">*</span>
        </label>
        <div className="mt-1">
          <textarea
            id="description"
            name="description"
            rows={3}
            value={formData.description}
            onChange={handleChange}
            className={`block w-full rounded-md border ${
              errors.description ? 'border-red-300' : 'border-gray-300'
            } shadow-sm py-2 px-3 focus:border-blue-500 focus:ring-blue-500`}
          />
          {errors.description && (
            <p className="mt-1 text-sm text-red-600">{errors.description}</p>
          )}
        </div>
      </div>
      
      <div>
        <label htmlFor="status" className="block text-sm font-medium text-gray-700 mb-1">
          Status
        </label>
        <div className="mt-1">
          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
            className="block w-full rounded-md border border-gray-300 shadow-sm py-2 px-3 focus:border-blue-500 focus:ring-blue-500"
          >
            <option value="Active">Active</option>
            <option value="Inactive">Inactive</option>
          </select>
        </div>
      </div>
      
      <div className="flex justify-end space-x-3">
        <button
          type="button"
          onClick={onCancel}
          className="px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-50"
        >
          Cancel
        </button>
        <button
          type="submit"
          disabled={isSubmitting}
          className="px-4 py-2 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed"
        >
          {isSubmitting 
            ? isEditing ? 'Updating...' : 'Creating...' 
            : isEditing ? 'Update Category' : 'Create Category'
          }
        </button>
      </div>
    </form>
  );
} 