interface Category {
  id: string;
  name: string;
  slug: string;
  description: string;
  status: 'Active' | 'Inactive';
  productCount: number;
  createdAt: string;
  updatedAt: string;
}

interface CreateCategoryInput {
  name: string;
  slug: string;
  description: string;
  status: 'Active' | 'Inactive';
}

interface UpdateCategoryInput {
  name?: string;
  slug?: string;
  description?: string;
  status?: 'Active' | 'Inactive';
}

// Utility to ensure properly formatted URL
function ensureValidUrl(url: string): string {
  // Make sure there are no double slashes except for the protocol
  return url.replace(/([^:]\/)\/+/g, "$1");
}

// Get all categories
export async function getCategories(): Promise<{ categories: Category[] }> {
  try {
    console.log('Fetching all categories');
    const response = await fetch('/api/categories', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      cache: 'no-store'
    });
    
    if (!response.ok) {
      const errorData = await response.json();
      console.error('Error response from categories API:', errorData);
      throw new Error(errorData.error || 'Failed to fetch categories');
    }
    
    const data = await response.json();
    console.log(`Fetched ${data.categories?.length || 0} categories`);
    return data;
  } catch (error) {
    console.error('Error fetching categories:', error);
    return { categories: [] };
  }
}

// Get a single category by ID
export async function getCategoryById(id: string): Promise<{ category: Category | null }> {
  try {
    console.log(`Fetching category with ID: ${id}`);
    const url = ensureValidUrl(`/api/categories/${id}`);
    console.log(`Request URL: ${url}`);
    
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      cache: 'no-store'
    });
    
    console.log(`Get category response status: ${response.status}`);
    
    if (!response.ok) {
      const errorData = await response.json();
      console.error('Error response from category API:', errorData);
      throw new Error(errorData.error || 'Failed to fetch category');
    }
    
    const data = await response.json();
    console.log('Category data received:', data);
    return data;
  } catch (error) {
    console.error(`Error fetching category with ID ${id}:`, error);
    return { category: null };
  }
}

// Create a new category
export async function createCategory(categoryData: CreateCategoryInput): Promise<string | null> {
  try {
    console.log('Creating new category with data:', categoryData);
    
    const response = await fetch('/api/categories', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(categoryData),
      cache: 'no-store'
    });
    
    console.log(`Create category response status: ${response.status}`);
    const responseData = await response.json();
    console.log('Create response data:', responseData);
    
    if (!response.ok) {
      throw new Error(responseData.error || 'Failed to create category');
    }
    
    return responseData.categoryId;
  } catch (error) {
    console.error('Error creating category:', error);
    return null;
  }
}

// Update a category
export async function updateCategory(id: string, categoryData: UpdateCategoryInput): Promise<boolean> {
  try {
    console.log(`Updating category ${id} with data:`, categoryData);
    const url = ensureValidUrl(`/api/categories/${id}`);
    console.log(`PUT request URL: ${url}`);
    
    // Add a timestamp to avoid caching
    const timestamp = new Date().getTime();
    const urlWithTimestamp = `${url}?t=${timestamp}`;
    
    const response = await fetch(urlWithTimestamp, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'Cache-Control': 'no-cache'
      },
      body: JSON.stringify(categoryData),
      cache: 'no-store'
    });
    
    console.log(`Update response status: ${response.status}`);
    const responseData = await response.json();
    console.log('Update response data:', responseData);
    
    if (!response.ok) {
      throw new Error(responseData.error || 'Failed to update category');
    }
    
    return true;
  } catch (error) {
    console.error(`Error updating category with ID ${id}:`, error);
    return false;
  }
}

